import{_ as t,o,c as a,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const h=JSON.parse('{"title":"Computation inventory","description":"","frontmatter":{},"headers":[],"relativePath":"reference/09-computation-inventory.md","filePath":"reference/09-computation-inventory.md","lastUpdated":1788720195000}'),n={name:"reference/09-computation-inventory.md"};function r(s,e,c,l,p,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="computation-inventory" tabindex="-1">Computation inventory <a class="header-anchor" href="#computation-inventory" aria-label="Permalink to &quot;Computation inventory&quot;">​</a></h1><p>The canonical inventory of production computations is <a href="computations.json"><code>computations.json</code></a>. Its structural contract is <a href="computations.schema.json"><code>computations.schema.json</code></a>, and the repository enforces the stronger cross-file rules with <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/tools/check_computation_inventory.py" target="_blank" rel="noreferrer"><code>tools/check_computation_inventory.py</code></a>.</p><p>Repository-wide catalogue counts are derived into <a href="project-facts.json"><code>project-facts.json</code></a>. Run <code>python tools/check_documentation_freshness.py --write</code> after intentionally changing calculation systems, cities, MCP tools, activity catalogues, or the computation inventory. The normal <code>tools/verify_project.py</code> command fails if that generated snapshot or the high-level documentation has drifted.</p><p>The inventory answers these questions for each conceptual computation:</p><ul><li>What stable ID names it?</li><li>Which implementation owns it, and which implementations mirror or consume it?</li><li>What are its inputs, outputs, and time basis?</li><li>Which public or internal surfaces expose it?</li><li>Which provenance claims and verification states apply?</li><li>Which tests exercise it, and what limitations remain?</li></ul><p>Stable IDs are durable documentation anchors. They should survive file moves and refactors when the meaning of the computation has not changed. New production computations must add a record; retired computations must remove or explicitly replace their record.</p><h2 id="scope-boundary" tabindex="-1">Scope boundary <a class="header-anchor" href="#scope-boundary" aria-label="Permalink to &quot;Scope boundary&quot;">​</a></h2><p>The inventory records domain computations, not every function. A computation is a meaningful astronomical result, Panchangam fact or window, derived classification, personal calculation, scoring decision, or interpretive result. One conceptual computation can have several implementation links when, for example, Python owns the calculation and TypeScript mirrors it in the browser.</p><p>Source files that own no domain calculation are classified explicitly under <code>coverage.exclusions</code>. Valid exclusions include package markers, lookup data, data models, adapters, orchestration, serialization, and UI-only code. The validator audits the configured Python and TypeScript source roots, so a new production file cannot remain silently unclassified.</p><h2 id="assurance-language" tabindex="-1">Assurance language <a class="header-anchor" href="#assurance-language" aria-label="Permalink to &quot;Assurance language&quot;">​</a></h2><p>Inventory coverage does not mean that every result has been independently verified. Each record carries its actual evidence class and verification state:</p><ul><li>tests show that the repository&#39;s current behavior is reproducible;</li><li>provenance links show what source or comparison supports the claim;</li><li><code>partially_verified</code>, <code>needs_locator</code>, <code>conflicted</code>, and similar states expose incomplete evidence instead of implying blanket correctness;</li><li>limitations state important convention, accuracy, scope, or safety boundaries.</li></ul><p>The claim-level source register remains <a href="provenance.json"><code>provenance.json</code></a>. The computation inventory links to it; it does not replace it.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Run the inventory contract directly from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/check_computation_inventory.py</span></span></code></pre></div><p>The command validates IDs, vocabularies, required metadata, source symbols, test paths, provenance claim links, implementation ownership, explicit exclusions, and complete classification of the configured production source roots. Its successful summary prints the current record, implementation, and audited-file counts.</p><p>The same contract is exercised by <code>tests/test_computation_inventory.py</code>, so it also runs as part of the normal Python test suite.</p><h2 id="updating-the-inventory" tabindex="-1">Updating the inventory <a class="header-anchor" href="#updating-the-inventory" aria-label="Permalink to &quot;Updating the inventory&quot;">​</a></h2><ol><li>Choose a stable conceptual ID; do not encode a file path into it.</li><li>Link the owner implementation and every material mirror or consumer.</li><li>Record inputs, outputs, time basis, exposed surfaces, evidence, tests, and limitations at the precision actually supported.</li><li>Add any genuinely non-computational new source file to the explicit exclusion list with a narrow reason.</li><li>Run the validator and the relevant computation tests before opening a PR.</li></ol><p>If the inventory reveals a computation defect or evidence conflict, open a separate correction or research story. Do not silently change a frozen engine while updating documentation.</p>',21)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
